CREATE TABLE dxf_document (id INTEGER PRIMARY KEY CHECK (id = 1), schema TEXT NOT NULL);
CREATE TABLE dxf_header (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dxf_document(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, group_code INTEGER NOT NULL, value_kind TEXT NOT NULL CHECK (value_kind IN ('str','int','double','point')), string_value TEXT, integer_value INTEGER, double_value REAL, point_x REAL, point_y REAL, point_z REAL, double_value_bits INTEGER, double_value_class TEXT CHECK (double_value_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_x_bits INTEGER, point_x_class TEXT CHECK (point_x_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_y_bits INTEGER, point_y_class TEXT CHECK (point_y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_z_bits INTEGER, point_z_class TEXT CHECK (point_z_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE dxf_layer (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dxf_document(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, color INTEGER NOT NULL, linetype TEXT NOT NULL, flags INTEGER NOT NULL);
CREATE TABLE dxf_style (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dxf_document(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, flags INTEGER NOT NULL, font_name TEXT NOT NULL);
CREATE TABLE dxf_linetype (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dxf_document(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, flags INTEGER NOT NULL, description TEXT NOT NULL);
CREATE TABLE dxf_other_table (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dxf_document(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL);
CREATE TABLE dxf_raw_tag (id INTEGER PRIMARY KEY, table_id INTEGER NOT NULL REFERENCES dxf_other_table(id), ordinal INTEGER NOT NULL, group_code INTEGER NOT NULL, value TEXT NOT NULL);
CREATE TABLE dxf_block (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dxf_document(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, base_x REAL, base_y REAL, base_z REAL, base_x_bits INTEGER, base_x_class TEXT CHECK (base_x_class IN ('finite','positiveInfinity','negativeInfinity','nan')), base_y_bits INTEGER, base_y_class TEXT CHECK (base_y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), base_z_bits INTEGER, base_z_class TEXT CHECK (base_z_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE dxf_entity (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES dxf_document(id), block_id INTEGER REFERENCES dxf_block(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('line','circle','arc','polyline','text','solid','insert','other')), layer TEXT, radius REAL, start_angle REAL, end_angle REAL, text_height REAL, text_value TEXT, block_name TEXT, scale_x REAL, scale_y REAL, scale_z REAL, rotation REAL, closed INTEGER CHECK (closed IN (0,1)), other_kind TEXT, radius_bits INTEGER, radius_class TEXT CHECK (radius_class IN ('finite','positiveInfinity','negativeInfinity','nan')), start_angle_bits INTEGER, start_angle_class TEXT CHECK (start_angle_class IN ('finite','positiveInfinity','negativeInfinity','nan')), end_angle_bits INTEGER, end_angle_class TEXT CHECK (end_angle_class IN ('finite','positiveInfinity','negativeInfinity','nan')), text_height_bits INTEGER, text_height_class TEXT CHECK (text_height_class IN ('finite','positiveInfinity','negativeInfinity','nan')), scale_x_bits INTEGER, scale_x_class TEXT CHECK (scale_x_class IN ('finite','positiveInfinity','negativeInfinity','nan')), scale_y_bits INTEGER, scale_y_class TEXT CHECK (scale_y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), scale_z_bits INTEGER, scale_z_class TEXT CHECK (scale_z_class IN ('finite','positiveInfinity','negativeInfinity','nan')), rotation_bits INTEGER, rotation_class TEXT CHECK (rotation_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE dxf_entity_point (id INTEGER PRIMARY KEY, entity_id INTEGER NOT NULL REFERENCES dxf_entity(id), ordinal INTEGER NOT NULL, role TEXT NOT NULL CHECK (role IN ('start','end','center','position','corner')), x REAL, y REAL, z REAL, x_bits INTEGER, x_class TEXT CHECK (x_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y_bits INTEGER, y_class TEXT CHECK (y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), z_bits INTEGER, z_class TEXT CHECK (z_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE dxf_vertex (id INTEGER PRIMARY KEY, entity_id INTEGER NOT NULL REFERENCES dxf_entity(id), ordinal INTEGER NOT NULL, x REAL, y REAL, z REAL, bulge REAL, x_bits INTEGER, x_class TEXT CHECK (x_class IN ('finite','positiveInfinity','negativeInfinity','nan')), y_bits INTEGER, y_class TEXT CHECK (y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), z_bits INTEGER, z_class TEXT CHECK (z_class IN ('finite','positiveInfinity','negativeInfinity','nan')), bulge_bits INTEGER, bulge_class TEXT CHECK (bulge_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE dxf_group_code (id INTEGER PRIMARY KEY, header_id INTEGER REFERENCES dxf_header(id), layer_id INTEGER REFERENCES dxf_layer(id), style_id INTEGER REFERENCES dxf_style(id), linetype_id INTEGER REFERENCES dxf_linetype(id), block_id INTEGER REFERENCES dxf_block(id), entity_id INTEGER REFERENCES dxf_entity(id), vertex_id INTEGER REFERENCES dxf_vertex(id), ordinal INTEGER NOT NULL, group_code INTEGER NOT NULL, value_kind TEXT NOT NULL CHECK (value_kind IN ('str','int','double','point')), string_value TEXT, integer_value INTEGER, double_value REAL, point_x REAL, point_y REAL, point_z REAL, double_value_bits INTEGER, double_value_class TEXT CHECK (double_value_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_x_bits INTEGER, point_x_class TEXT CHECK (point_x_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_y_bits INTEGER, point_y_class TEXT CHECK (point_y_class IN ('finite','positiveInfinity','negativeInfinity','nan')), point_z_bits INTEGER, point_z_class TEXT CHECK (point_z_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
